-- ---------------------------------------------------------------------
DELETE FROM `collect_flow`
WHERE `collect_flow_code` IN (
        'demo-variable-snapshot',   -- 示例-平台变量快照
        'demo-github-repo'          -- 示例-GitHub 项目采集
      );

-- ---------------------------------------------------------------------
-- 二、清理仅为演示流程服务的示例分类与全局变量
-- ---------------------------------------------------------------------
DELETE FROM `collect_category`
WHERE `collect_category_id` = 1
  AND `collect_category_name` = '示例采集';

DELETE FROM `collect_variable`
WHERE `collect_variable_id` IN (1, 2)
  AND `collect_variable_name` IN ('snapshotUrl', 'demoDate');

